from pathlib import Path
import html
people=[
('theseus','테세우스','주인공 · 영웅','짙은 갈색 곱슬머리, 따뜻한 갈색 눈, 날렵한 소년형 얼굴. 왕이 된 뒤에는 턱선과 눈가에 경험의 무게를 더한다.','아버지의 검 · 붉은 망토 · 낡은 가죽 신발','바다색 #254f69 · 테라코타 #c45c37','두려워도 먼저 앞으로 나아간다. 승리 뒤에는 반드시 선택의 결과를 바라보는 짧은 정적을 둔다.','아리아드네에게는 감사와 미안함, 아이게우스에게는 사랑과 죄책감, 미노타우로스 앞에서는 두려움 속 결심.'),
('ariadne','아리아드네','조력자 · 길잡이','긴 밤색 머리, 또렷한 눈썹, 차분한 눈빛. 움직임은 작고 정확하며 손끝에 지혜가 드러난다.','붉은 실타래 · 금빛 머리핀 · 푸른 소매','자주 #6a3f5e · 산호 #e58b72','말보다 준비와 배려로 마음을 보여준다. 미궁 장면에서도 시선은 흔들리지 않는다.','테세우스에게는 신뢰와 애정, 미궁에는 통찰, 떠나는 순간에는 상처를 절제된 표정으로 표현.'),
('aegeus','아이게우스','왕 · 아버지','넓은 어깨, 짧은 회갈색 수염, 단단한 왕의 자세. 테세우스를 볼 때만 눈가가 부드러워진다.','청동 왕관 · 흰 돛과 검은 돛 · 왕의 청색 망토','청회색 #4e6876 · 모래 #d5b08c','사랑이 큰 만큼 걱정도 크게 드러난다. 돛을 보는 장면은 먼 거리에서도 실루엣이 읽혀야 한다.','테세우스에게는 자랑과 불안, 검은 돛에는 믿음이 무너지는 순간의 정지, 바다에는 작은 인간의 실루엣.'),
('minotaur','미노타우로스','신화적 적 · 미궁의 수호자','소의 머리와 사람의 몸. 큰 뿔, 거친 털, 무거운 어깨. 눈에는 괴물성보다 갇힌 존재의 외로움을 남긴다.','부서진 돌기둥 · 미궁의 벽 그림자 · 검은 발굽','흑청 #171d24 · 황토 #9b765e','포효는 크고 움직임은 느리다. 좁은 패널에서는 뿔과 그림자로 압도감을 만든다.','테세우스에게는 적의 본능, 아이들에게는 공포, 마지막에는 오래 갇혀 있던 존재의 고독.'),
('aethra','아에트라','어머니 · 출발의 중심','짙은 머리카락을 낮게 묶고, 바닷바람에 흔들리는 연한 숄을 두른다. 따뜻한 표정과 단단한 손을 함께 가진다.','돌 아래의 신발 · 짠 숄 · 작은 기도 부적','밤색 #34253d · 모래분홍 #dca084','짧은 말 안에 신뢰와 걱정을 함께 담는다. 테세우스를 붙잡지 않고 보내는 인물이다.','테세우스에게는 믿음과 걱정, 돌을 들어 올리는 순간에는 자부심, 이별에는 말 없는 응원.')]
template='''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{name} · Character Sheet</title><style>*{{box-sizing:border-box}}body{{margin:0;background:#151923;color:#f8f2e9;font-family:system-ui,-apple-system,sans-serif}}header{{padding:20px 6vw;border-bottom:1px solid #38404f;display:flex;justify-content:space-between}}a{{color:#ffb28e;text-decoration:none}}main{{max-width:1100px;margin:auto;padding:44px 24px 80px}}.kicker{{color:#ff8f6b;font-weight:800;letter-spacing:.16em;font-size:.76rem}}h1{{font-size:clamp(3rem,8vw,7rem);line-height:.9;margin:12px 0;color:#79d3dc}}.role{{font-weight:700;color:#ff9a76;font-size:1.05rem}}.layout{{display:grid;grid-template-columns:330px 1fr;gap:28px;margin-top:36px}}.portrait{{min-height:500px;border-radius:24px;background:linear-gradient(135deg,{c2},{c1});border:1px solid #4c586b;position:relative;overflow:hidden}}.portrait:before{{content:'';position:absolute;width:220px;height:270px;left:50%;bottom:20px;transform:translateX(-50%);border-radius:48% 48% 34% 34%;background:#e7ad8a;box-shadow:0 -58px 0 32px {hair},0 48px 0 62px {shirt}}}.portrait:after{{content:'✦';position:absolute;right:22px;top:18px;font-size:3rem;color:#fff9}}.panel{{background:#202633;border:1px solid #394252;border-radius:20px;padding:26px;margin-bottom:18px}}h2{{font-size:1.2rem;color:#79d3dc;margin:0 0 12px}}p,li{{color:#c2cad3;line-height:1.75}}ul{{padding-left:20px}}.swatch{{display:inline-flex;align-items:center;gap:8px;margin:4px 14px 4px 0;color:#dfe7ed}}.dot{{width:18px;height:18px;border-radius:50%;background:{c1};display:inline-block;border:1px solid #fff5}}.dot.two{{background:{c2}}}.back{{font-weight:700}}@media(max-width:760px){{.layout{{grid-template-columns:1fr}}.portrait{{min-height:260px}}}} </style></head><body><header><a class="back" href="characters.html">← Character Bible</a><a href="index.html">이야기로 돌아가기</a></header><main><div class="kicker">KOREAN WEBTOON CHARACTER SHEET</div><h1>{name}</h1><div class="role">{role}</div><div class="layout"><div class="portrait"></div><div><section class="panel"><h2>외형 고정점</h2><p>{appearance}</p></section><section class="panel"><h2>고정 소품</h2><p>{props}</p></section><section class="panel"><h2>색상 팔레트</h2><div class="swatch"><i class="dot"></i>{c1}</div><div class="swatch"><i class="dot two"></i>{c2}</div></section><section class="panel"><h2>장면 연기 지침</h2><p>{acting}</p></section><section class="panel"><h2>관계와 감정선</h2><p>{relationships}</p></section><section class="panel"><h2>연속성 체크</h2><ul><li>머리 모양과 실루엣을 장면마다 유지</li><li>고정 소품은 색상과 위치를 임의로 바꾸지 않기</li><li>감정 변화는 눈썹·시선·손의 순서로 표현</li></ul></section></div></div></main></body></html>'''
for slug,name,role,appearance,props,c1,acting,relationships in people:
 c2={'#c45c37':'#244657','#e58b72':'#6a3f5e','#d5b08c':'#3b506d','#9b765e':'#263642','#dca084':'#4b3045'}[c1]
 hair={'테세우스':'#241f32','아리아드네':'#4a1f35','아이게우스':'#5b3628','미노타우로스':'#171d24','아에트라':'#34253d'}[name]
 shirt={'테세우스':'#274f69','아리아드네':'#c35c55','아이게우스':'#4e6876','미노타우로스':'#677d86','아에트라':'#87516b'}[name]
 out=template.format(name=name,role=role,appearance=appearance,props=props,c1=c1,c2=c2,hair=hair,shirt=shirt,acting=acting,relationships=relationships)
 Path(f'character-{slug}.html').write_text(out,encoding='utf-8')
 Path(f'dist/character-{slug}.html').write_text(out,encoding='utf-8')
# add links to cards by h2 occurrence
p=Path('characters.html'); s=p.read_text(encoding='utf-8')
for slug,name,*_ in people: s=s.replace(f'<h2>{name}</h2>',f'<h2><a href="character-{slug}.html">{name}</a></h2>')
p.write_text(s,encoding='utf-8'); Path('dist/characters.html').write_text(s,encoding='utf-8')
